SELECT ws.web_site_id, ws.web_name, d_start.d_quarter_name AS quarter, COUNT(DISTINCT cp.cp_catalog_page_id) AS distinct_pages, AVG(cp.cp_catalog_number) AS avg_catalog_number, MIN(d_start.d_date) AS quarter_start_date, MAX(d_start.d_date) AS quarter_end_date FROM catalog_page cp JOIN date_dim d_start ON cp.cp_start_date_sk = d_start.d_date_sk JOIN web_site ws ON d_start.d_date_sk BETWEEN ws.web_open_date_sk AND ws.web_close_date_sk JOIN date_dim d_open ON ws.web_open_date_sk = d_open.d_date_sk JOIN date_dim d_close ON ws.web_close_date_sk = d_close.d_date_sk WHERE cp.cp_type = 'monthly' AND date_diff('day', d_open.d_date, d_close.d_date) >= 180 AND d_start.d_year = 1999 GROUP BY ws.web_site_id, ws.web_name, d_start.d_quarter_name HAVING COUNT(DISTINCT cp.cp_catalog_page_id) > 5 ORDER BY distinct_pages DESC, ws.web_site_id LIMIT 100
